class Solution {
    public String reverseLeftWords(String s, int n) {
        char[] a = s.toCharArray();
        if (a.length == 0) return s;
        n %= a.length;
        rev(a, 0, n - 1);
        rev(a, n, a.length - 1);
        rev(a, 0, a.length - 1);
        return new String(a);
    }

    private void rev(char[] a, int i, int j) {
        while (i < j) {
            char t = a[i];
            a[i] = a[j];
            a[j] = t;
            i++;
            j--;
        }
    }
}

