class Solution {
    public int evalRPN(String[] tokens) {
        int[] st = new int[tokens.length];
        int top = 0;
        for (String tk : tokens) {
            if (tk.equals("+") || tk.equals("-") || tk.equals("*") || tk.equals("/")) {
                int b = st[--top], a = st[--top];
                if (tk.equals("+")) st[top++] = a + b;
                else if (tk.equals("-")) st[top++] = a - b;
                else if (tk.equals("*")) st[top++] = a * b;
                else st[top++] = a / b;
            } else {
                st[top++] = Integer.parseInt(tk);
            }
        }
        return st[top - 1];
    }
}

