class TreeNode {
    int val;
    TreeNode left, right;

    TreeNode(int v) { val = v; }
}

class Solution {
    private final Map<Integer, Integer> pos = new HashMap<>();
    private int[] post;

    public TreeNode buildTree(int[] inorder, int[] postorder) {
        post = postorder;
        for (int i = 0; i < inorder.length; i++) pos.put(inorder[i], i);
        return build(0, inorder.length - 1, postorder.length - 1);
    }

    private TreeNode build(int l, int r, int pr) {
        if (l > r) return null;
        TreeNode root = new TreeNode(post[pr]);
        int k = pos.get(root.val);
        root.left = build(l, k - 1, pr - (r - k) - 1);
        root.right = build(k + 1, r, pr - 1);
        return root;
    }
}

