    static String next() throws IOException {
        while (!tk.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            tk = new StringTokenizer(line);
        }
        return tk.nextToken();
    }

    static TreeNode buildTree(int[] in, int[] post, Map<Integer, Integer> pos) {
        return go(in, post, pos, 0, in.length - 1, post.length - 1);
    }

    static TreeNode go(int[] in, int[] post, Map<Integer, Integer> pos,
                       int l, int r, int pr) {
        if (l > r) return null;
        TreeNode root = new TreeNode(post[pr]);
        int k = pos.get(root.val);
        root.left = go(in, post, pos, l, k - 1, pr - (r - k) - 1);
        root.right = go(in, post, pos, k + 1, r, pr - 1);
        return root;
    }

    static String serialize(TreeNode root) {
        if (root == null) return "[]";
        List<String> parts = new ArrayList<>();
        List<TreeNode> q = new ArrayList<>();
        q.add(root);
        int head = 0;
        while (head < q.size()) {
            TreeNode node = q.get(head++);
            if (node == null) {
                parts.add("null");
                continue;
            }
            parts.add(String.valueOf(node.val));
            q.add(node.left);
            q.add(node.right);
        }
        int end = parts.size();
        while (end > 0 && parts.get(end - 1).equals("null")) end--;
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < end; i++) {
            if (i > 0) sb.append(',');
            sb.append(parts.get(i));
        }
        sb.append(']');
        return sb.toString();
    }

